mod fixture {
    include!("/home/dev-user/.codex/worktrees/toucan-bool-macros/crates/toucan/tests/bool_macros.rs");
    pub fn emit(directory: &Path, target: Target) {
        let compilation=parse(target);
        for (index,(mut options,booleans)) in cases().into_iter().enumerate() {
            options.rust_target=RustTarget::RUST_1_64;
            let output=directory.join(index.to_string());std::fs::create_dir_all(&output).unwrap();
            let (source,report)=compilation.bindings(&options).unwrap();
            std::fs::write(output.join("bindings.rs"),source).unwrap();
            std::fs::write(output.join("report.json"),serde_json::to_vec_pretty(&report).unwrap()).unwrap();
            let mut consumer=String::from("#![allow(non_camel_case_types,non_upper_case_globals,dead_code)]\nmod b{include!(\"bindings.rs\");}\n");
            for name in BOOL_NAMES {
                let rust_name=if *name=="type"{"r#type"}else{name};
                let ty=if booleans.contains(name){"bool"}else{"u32"};
                consumer.push_str(&format!("const _: {ty} = b::{rust_name};\n"));
            }
            std::fs::write(output.join("consumer.rs"),consumer).unwrap();
        }
    }
}
fn main(){let args:Vec<_>=std::env::args().collect();fixture::emit(std::path::Path::new(&args[1]),toucan::Target::parse(&args[2]).unwrap());}
